const raw = ($input.first()?.json?.text ?? $input.first()?.json?.output ?? '').toString();
let facts = [];

const stripOuterQuotes = (value) => String(value ?? '')
  .replace(/^['"“”]+|['"“”]+$/g, '')
  .trim();

const removeVietnameseMarks = (value) => value
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/đ/g, 'd')
  .replace(/Đ/g, 'D');

const normalizePhone = (value) => {
  const raw = String(value ?? '').replace(/[^\d+]/g, '');
  let phone = raw;
  if (phone.startsWith('+84')) phone = '0' + phone.slice(3);
  if (phone.startsWith('84') && phone.length >= 11) phone = '0' + phone.slice(2);
  return /^0\d{8,10}$/.test(phone) ? phone : null;
};

const canonicalize = (value) => {
  const stripped = stripOuterQuotes(value);
  const phone = normalizePhone(stripped);
  if (phone) return `phone:${phone}`;

  return removeVietnameseMarks(stripped)
    .toLowerCase()
    .replace(/^(nguoi dung|ung vien|ban ay|ban)\s+/i, '')
    .replace(/^(sdt|so dien thoai|dien thoai|khu vuc|nghe mong muon|muon|muon tim viec|ten la)[:\s-]*/i, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
};

const normalizeFact = (value) => stripOuterQuotes(value)
  .replace(/\s+/g, ' ')
  .trim();

const isUsefulFact = (fact) => {
  if (!fact) return false;
  if (fact.length < 6 || fact.length > 240) return false;
  if (/^(xin chào|chào bạn|cảm ơn|tôi có thể|bạn đang muốn|bạn có muốn)/i.test(fact)) return false;
  if (/^(tên công việc|công ty\/?đối tác|địa điểm|mức lương|yêu cầu cơ bản|quyền lợi):/i.test(fact)) return false;
  return true;
};

try {
  let text = raw.trim()
    .replace(/^\x60\x60\x60(?:json)?/i, '')
    .replace(/\x60\x60\x60$/i, '')
    .trim();
  const start = text.indexOf('[');
  const end = text.lastIndexOf(']');
  if (start !== -1 && end !== -1 && end > start) text = text.slice(start, end + 1);

  const parsed = JSON.parse(text);
  if (Array.isArray(parsed)) {
    const seen = new Set();
    facts = parsed
      .map(normalizeFact)
      .filter(isUsefulFact)
      .map((content) => ({ content, canonical_key: canonicalize(content) }))
      .filter((fact) => fact.canonical_key)
      .filter((fact) => {
        if (seen.has(fact.canonical_key)) return false;
        seen.add(fact.canonical_key);
        return true;
      });
  }
} catch (error) {
  facts = [];
}

return facts.slice(0, 10).map((fact) => ({ json: { ...fact, source: 'candidate' } }));

